set-variable.value:
@{
    try {
      if (!context.Variables.ContainsKey("byokCallerAuthenticated") || !(bool)context.Variables["byokCallerAuthenticated"]
          || !context.Variables.ContainsKey("byokResponseOwnerMarkers")
          || !context.Variables.ContainsKey("byokResponseReference")
          || !context.Variables.ContainsKey("byokResponseOwnershipDocument")) { return false; }
      var reference = (string)context.Variables["byokResponseReference"];
      if (!System.Text.RegularExpressions.Regex.IsMatch(reference, @"\Aresp_[A-Za-z0-9_-]{1,128}\z")) { return false; }
      var document = Newtonsoft.Json.Linq.JObject.Parse((string)context.Variables["byokResponseOwnershipDocument"]);
      if (document["id"]?.Type != Newtonsoft.Json.Linq.JTokenType.String || (string)document["id"] != reference
          || document["object"]?.Type != Newtonsoft.Json.Linq.JTokenType.String || (string)document["object"] != "response") { return false; }
      var metadata = document["metadata"] as Newtonsoft.Json.Linq.JObject;
      var marker = metadata?["byok_owner_v1"];
      if (marker?.Type != Newtonsoft.Json.Linq.JTokenType.String
          || !System.Text.RegularExpressions.Regex.IsMatch((string)marker, @"\Av1\.[0-9a-f]{64}\z")) { return false; }
      foreach (var expected in ((string)context.Variables["byokResponseOwnerMarkers"]).Split(',')) {
        if (!System.Text.RegularExpressions.Regex.IsMatch(expected, @"\Av1\.[0-9a-f]{64}\z")) { return false; }
        var difference = 0;
        for (var characterIndex = 0; characterIndex < expected.Length; characterIndex++) { difference |= expected[characterIndex] ^ ((string)marker)[characterIndex]; }
        if (difference == 0) { return true; }
      }
      return false;
    } catch { return false; }
  }
